import unittest
from stream.pipeline import StreamPipeline

class TestStreamPipeline(unittest.TestCase):
    def test_window(self):
        sp = StreamPipeline(window_size=2)
        self.assertIsNone(sp.push(1.0))
        self.assertEqual(sp.push(2.0), [1.0, 2.0])
        self.assertEqual(sp.push(3.0), [2.0, 3.0])

if __name__ == '__main__': unittest.main()
